	title 'Tool Locator--Mount'*****************************************************************************			               **	               Mount	               **			               **********************************************************************************************************************************************************			   *	CopyRight Apple Computer, Inc. 1985-1989	   *	All Rights Reserved		   *			   *			   * 21 Feb 89	Harry Yee		   ** Fixed problem in TLTextMountVolume and TLMountVolume. Before we were calling  * GetNextEvent which caused problems if there happened to be a system window * beneath us. Key downs and mouse downs were never getting back to the tool locator    * because they were passed onto the Desk Mgr via SystemEvent. Now I call GetOSEvent  * which doesn't call the Desk Mgr and if there was a desk accessary event * i.e. <ctrl><open-apple><esc> I pass on this event to the Desk Mgr myself * via SystemEvent. BRC #41721. ** Also for TLTextMountVolume we were not taking mouse downs or mouse ups. This* caused problems if the user was clicking the mouse while in the text screen because* when they finally returned to the program all the mouse events would be queued up.* I now take mouse events and just discard them.*****************************************************************************	blanks off	string asis	print push	print off	include 'all.macros'	include '::sys.equs.asm'	INCLUDE 'e16.memory'	include 'e16.event'	include 'tl.equates.asm'	print pop	title ' Imported Addresses';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT EndCall4	IMPORT EndCall8	IMPORT ErrOut4	IMPORT ErrOut8	IMPORT oBusyErr4	IMPORT oEndCall0	eject*****************************************************************TLMountVolume	PROC EXPORT** This is the mount	volume call that is	part of the tool* locator.  Why is it part of the tool locator?  A very good* question.  It is part of the tool locator because it* needs to be loaded and stay loaded when other tools* cannot be loaded.** For example, an application calls load tools which fails* because the the boot volume is not on	line.  The application* cannot call a tool that is not loaded	to tell the user to* insert the disk.** So this routine does this work for the desk top application.* It does not do the work for a text, lo res or hi-res* application.  Such routines are left as exercises to the* application writer.** Assumptions:**     1) QuickDraw is already initialized so I can safely make*        QuickDraw calls.*     2) Event Manager is already initialized so I can safely*        make Event	manager calls.*     3) Memory will be available.*** This routine actually makes no OS calls.  It just returns* the button number	pressed by the user.  The application* then can make the	call that failed again and see if it* works.** By not guarenteeing the volume is mounted this routine is* more general (and	shorter).**** Inputs:*              WhereX : word*              WhereY : word*              PromptPtr : long*              VolPtr : long*              OKPtr : long*              CancelPtr : long** Outputs:*              ButtonSelected : word** External Refs:	import TLGetMem2** Entry Points:*	none*	longa on	; mode	longi on** Change History** 17 Jun 88	Steven Glass** Removed internal copy of TLGetMem and used the global version.* Why we had a separate copy, I don't know.*** 06 Jan 89	Steven Glass** Added error checking to routines that allocate memory.  If* error occurs, we try to call TLTextMountVolume.*****************************************************************;; Equates for dialog;DialogWidth	equ 280DialogHeight	equ 65ButWidth	equ 115ButHeight	equ 13Size320	equ DialogHeight*(8+DialogWidth)/2Size640	equ DialogHeight*(16+DialogWidth)/4Width320	equ 2+(DialogWidth/2)Width640	equ 4+(DialogWidth/4)LeftFace	equ 15PromptX	equ LeftFacePromptY	equ 15VolX	equ LeftFaceVolY	equ 30TopFace	equ 22	; space from bottom	of dialog toOKy	equ DialogHeight-TopFace+ButHeight-3Cancely	equ DialogHeight-TopFace+ButHeight-3;; Local Data;	DefineStackSaveHandle	longEvtWhat	wordEvtMessage	longEvtWhen	longEvtWhere	longEvtModifiers	wordTheEvent	equ EvtWhatOrigPort	longSizeofSaveSpace	long	; this is size of handleMountPortHandle	longMountPortPtr	longSaveSCB	word	; ds 2PtrToSaveSpace	long	; ds 4	       ; pointer to	memorySaveWidth	word	; ds 2SaveBounds	block 8	; dc i'0,0,200,640'SaveLocInfo	equ SaveSCBSrcRect	block 8DialogRect	equ SrcRectInnerDRect	block 8HLRect	block 8HiliteFlag	wordWhichButton	wordOrigD	word; Stack on entry;RTL1	block 3RTL2	block 3CancelPtr	longOKPtr	longVolPtr	longPromptPtr	longWhereY	wordWhereX	wordResult	wordSizeLocals	equ OrigD-1	eject	phd	tsc	sec	sbc #SizeLocals	tcs	tcd	phb	phk	plb	jsl IncBusyFlg	pha	pha	_GetPort	lda #180	ldx #$C000	; locked and fixed	jsr TLGetMem2	bcc @2	brl MemError1@2	sta MountPortHandle	stx MountPortHandle+2	lda [MountPortHandle]	sta MountPortPtr	ldy #2	lda [MountPortHandle],y	sta MountPortPtr+2	pei MountPortPtr+2	pei MountPortPtr	_OpenPort	bcc @1	brl PortError@1;------------------------------------------------------;; First I need to figure out how big the rectangle; that will be saved is so I can get a handle for it.;	lda [MountPortPtr]	sta SaveSCB	; put this in the save LocInfo	and #$0080	beq Mode320	lda #Width640	sta SaveWidth	lda #Size640	bra GotSizeMode320	lda #Width320	sta SaveWidth	lda #Size320GotSize	sta SizeofSaveSpace	stz SizeofSaveSpace+2;-------------------------------------------------;; Fix SaveLocInfo's	bounds rect.  This bounds; rect is identical	to the destrect.;	ldy #DestRect	ldx #SaveBounds	jsr MoveRect;------------------------------------------------------;; Set up important variables.  First SourceRect and; InnerDRect are calculated from WhereX, WhereY and; size contants.  InnerDRect is then calculated by; inseting its initial value.;	lda WhereX	sta SrcRect+2	sta InnerDRect+2	clc	adc #DialogWidth	sta SrcRect+6	sta InnerDRect+6	lda WhereY	sta SrcRect	sta InnerDRect	clc	adc #DialogHeight	sta SrcRect+4	sta InnerDRect+4	lda #InnerDRect	jsr PushDP	jsr WhichMode	beq Inset320	PushWord #4	bra ContInsetInset320	PushWord #2ContInset	PushWord #2	_InsetRect;------------------------------------------------------;; Get memory for the pixels being saved.;	lda SizeOfSaveSpace	ldx #$8000	; locked	jsr TLGetMem2	bcc @3	brl MemError2@3	sta SaveHandle	stx SaveHandle+2	lda [SaveHandle]	sta PtrToSaveSpace	ldy #2	lda [SaveHandle],y	sta PtrToSaveSpace+2	_HideCursor	; hide cursor to avoid stamping	PushLong #0	; build parameter block on the	PushWord #0	; stack for PaintPixels	PushLong #DestRect	lda #SrcRect	; we build it backwards.	jsr PushDP	lda #SaveLocInfo	jsr PushDP	pei MountPortPtr+2	pei MountPortPtr	jsr Paint	_ShowCursor	lda #DialogRect	; pointer to DialogRect	jsr PushDP	_EraseRect	jsr WhichMode	beq PS320	PushWord #2	bra FiniPenSizePS320	PushWord #1FiniPenSize	PushWord #1	_SetPenSize	lda #DialogRect	jsr PushDP	_FrameRect	lda #InnerDRect	jsr PushDP	_FrameRect	lda #DialogRect	jsr PushDP	_SetPortRect	PushWord #0	PushWord #0	_SetOrigin	jsr DrawDialog	jsr PlayWithIt	; returns 1 for ok,	2 for cancel	sta Result	pei MountPortPtr+2	; re init loc info in mount port	pei MountPortPtr	_InitPort	PushLong #0	; build parameter block on the	PushWord #0	; stack for PaintPixels	lda #SrcRect	; we build it backwards.	jsr PushDP	PushLong #DestRect	pei MountPortPtr+2	pei MountPortPtr	lda #SaveLocInfo	jsr PushDP	jsr Paint	pei SaveHandle+2	; free the memory	pei SaveHandle	_DisposeHandleGetOutHere	_SetPort	; restore orig port	jsr ClosePort	jsr DisposePortHandle	plb	tsc	clc	adc #SizeLocals	tcs	ldy #20	ldx #0	pld	jml ToBusyStrip;; Got mem error trying to get buffer for bits.  This is ; after port allocated.  So close port and fall into other error; routines.;MemError2	jsr ClosePort;; Got error opening grafPort.;PortError	jsr DisposePortHandle;; Got error getting memory for port.  Boy are we in trouble now.;MemError1;; Try to call TLTextMountVolume and keep fingers crossed.;	pha	pei PromptPtr+2	pei PromptPtr	pei VolPtr+2	pei VolPtr	pei OkPtr+2	pei OkPtr	pei CancelPtr+2	pei CancelPtr	_TLTextMountVolume	pla	sta Result	bra GetOutHereClosePort		pei MountPortPtr+2	; close our port	pei MountPortPtr	_ClosePort	rtsDisposePortHandle	pei MountPortHandle+2	pei MountPortHandle	_DisposeHandle	rts	eject;-------------------------------------------------;; Paint;; Calls paint pixels using PPParam block on stack; just above the rts adr.;; After calling paint pixels, it strips	22 bytes; off the stack.;Paint		; rtsadr	equ 1PPParams	equ 3	tsc	pea 0000	clc	adc #PPParams	pha	_PaintPixels	ply	tsc	clc	adc #22	tcs	phy	rts;-------------------------------------------------;; PushDP;; Pushes a long pointer to a value on direct page.; the offset on D is passed in the a-reg.;; Input:  a-reg    offset; Output: Stack;; Trashed:  a-reg;           x-reg; Preserved y-reg;PushDP		; 	plx	; get rts off stack	pea 0000	; push hi word of 0	pha	; get offset on D page onto stack	tdc	; get dpage value	clc	; add to offset and	adc 1,s	sta 1,s	; overstore	phx	; put back rts value	rts	eject;-------------------------------------------------;; WhichMode;; This routine returns 0 in the a-reg if the; screen is in 320 mode and nonzero if it is; in 640 mode.;WhichMode		; 	lda [MountPortPtr]	and #$0080	rts;-------------------------------------------------;; PlayWithIt;; This is the routine that gets events and waits for a; response from the	user.;PlayWithIt		; ;; --- The only events we want are MouseDown, MouseUp, KeyDown, AutoKeyDown and DeskAcc -------; 	lda #mDownMask+mUpMask+keyDownMask+autoKeyMask+deskAccMask	jsr GetThisEvent	beq PlayWithIt	; no event of that type in queue so keep looking	lda EvtWhat	; got something!	asl a	tax	jsr (EventTable,x)	bcc PlayWithIt	rtsEventTable	DC.W ignore	DC.W DoMouseDown	; 1	DC.W ignore	; 2 mouse up	DC.W DoKey	; 3	DC.W ignore	; 4 undefined	DC.W DoKey	; 5 auto key	DC.W ignore	; 6 update	DC.W ignore	; 7 undefined	DC.W ignore	; 8 activate 	DC.W ignore	; 9 switch	DC.W DoDeskAcc	; 10 deskAccEvt	eject;-------------------------------------------------;; GetThisEvent;; Called by PlayWithIt to read; character using event manager.;; Event mask is passed in a-reg.  boolean returned in a reg.;GetThisEvent		; 	pha	; space for result	pha	; use mask coming in	lda #TheEvent	jsr PushDP	_GetOSEvent		pla	rts	eject;-------------------------------------------------;; DoDeskAcc;; Called when a desk accessory event is returned from ; GetOSEvent. The desk accessory event occurs when; the user has typed <ctrl><open-apple><esc>.;; When we get this message we call SystemEvent to; handle it.;DoDeskAcc	pha	; space for result	ldx #EvtModifiers	; copy the contents of the event record, gottenloop	lda <0,x	; back from GetOSEvent as input to SystemEvent	pha	; event record is on stack, which is also 	dex	; currently our direct page	dex	cpx #EvtWhat-2	; are we past beginning of event record?	bne loop		_SystemEvent	pla	clc		rts		eject;-------------------------------------------------;; DoMouseDown;; Called when the mouse button goes down.;; Returns carry set	if the mouse button	goes back up inside; same button it went down in.  If carry is set then; a-reg has number of button.;; Modification History;; 31 Dec 86    SEG;;    Simple code reduction.  No changes	in features.;DoMouseDown		; 	lda #EvtWhere	; figure out where it is	jsr PushDP	_GlobalToLocal	lda #OKRect	jsr InRectLong	bne TrackOK	lda #CancelRect	jsr InRectLong	bne TrackCancelIgnore		; 	clc	; it was somewhere else	rtsTrackOk		; 	ldy #OKRect	; Put OKRect in HLRect	lda #1	; this will be result later	bra StartTrackingTrackCancel		; 	ldy #CancelRect	; Put CancelRect in	HLRect	lda #2StartTracking		; 	sta WhichButton	ldx #HLRect	jsr MoveRectMakeDark	lda #$8000	; and setting this flag	sta HiliteFlag	jsr DarkButtonCheckMouse	pha	; space for result	PushWord #0	; button 0	_WaitMouseUp	pla	beq ItsNowUp	; false means yes it is now up.	lda #EvtWhere	; its still down so	check to see if	jsr PushDP	_GetMouse	; it is still in the button	lda #HLRect	jsr InRectShort	beq NotIn	lda HiliteFlag	; Its in, check to see if but is still	beq MakeDark	; dark, if not, light it	bra CheckMouse	; otherwise try again.NotIn	lda HiliteFlag	; Its not in, check	to see but is dark	bne UnliteIt	; if yes, light it	bra CheckMouseUnliteIt	lda #0	sta HiliteFlag	jsr LightButton	bra CheckMouseItsNowUp		; ; button came up so return lit state	lda HiLiteFlag	beq Nevermind	jsr LightButton	lda WhichButton	; return button number	sec	; signal end of secession	rtsNeverMind	clc	; signal to continue	rts	eject;-------------------------------------------------;; InRect;; Returns whether or not the eventWhere	point is; in the rectangle passed in the a-reg;; The result is returned in the z flag.;    z-set means that ptinrect returned	false.;    z-clear means that ptinrect returned true.;; Modification History;; 31 Dec 86    SEG;;    New this day.;InRectShort		; 	pha	; space for result and save incoming;		; button.	lda #EvtWhere	jsr PushDP	lda 5,s	jsr PushDPJoinInRect	_PtInRect	pla	rtsInRectLong		; 	pha	lda #EvtWhere	jsr PushDP	lda 5,s	PushWord #OKRect>>16	pha	bra JoinInRect	eject;-------------------------------------------------;; DarkButton;; This is the routine that draws a hilited (dark) button.  It; uses WhichButton to tell which to draw.;; Modification History;; 31 Dec 86    SEG;;    Simple code reduction.  No changes	in features.;DarkButton		; 	jsr PushHLStuff	_PaintRRect	PushWord #$000F	_SetForeColor	PushWord #$0000	_SetBackColor	lda WhichButton	jsr DrawButString	rts;-------------------------------------------------;; LightButton;; This is the routine that draws the normal; (unhilited) buttons. It uses WhichButton to; determine which to draw.;; Modification History;; 31 Dec 86    SEG;;    Simple code reduction.  No changes	in;    features.;;LightButton		; 	jsr PushHLStuff	_EraseRRect	jsr PushHLStuff	_FrameRRect	PushWord #$0000	_SetForeColor	PushWord #$000F	_SetBackColor	lda WhichButton	jsr DrawButString	rts	eject;-------------------------------------------------;; PushHLStuff;; Modification History;; 31 Dec 86    SEG;;    New this day.;PushHLStuff		; 	ply	lda #HLRect	jsr PushDP	; preserves y-reg	PushWord #20	PushWord #10	phy	rts	eject;-------------------------------------------------;; DrawButString;; This routine draws the contents of a button.; The button to draw is passed in the a-reg;; Modification History;; 31 Dec 86    SEG;;    Simple code reduction.  No changes	in features.;;DrawButString		; 	cmp #1	bne DoCancel	pha	; figure string width to	pei OKPtr+2	; center string in button	pei OKPtr	_StringWidth	lda #ButWidth	sec	sbc 1,s	lsr a	clc	; add to left edge	adc OkRect+2	sta 1,s	; push result	PushWord #OKy	_MoveTo	pei OkPtr+2	; draw ok string	pei OKPtr	_DrawString	rtsDoCancel	pha	; do it all again.	pei CancelPtr+2	pei CancelPtr	_StringWidth	lda #ButWidth	sec	sbc 1,s	lsr a	clc	adc CancelRect+2	sta 1,s	PushWord #Cancely	_MoveTo	pei CancelPtr+2	pei CancelPtr	_DrawString	rts	eject;-------------------------------------------------;; DoKey;; This is the routine that checks key strokes; for RETURN and ESC.;; It returns with carry set if either are; pressed and the button number in the a-reg.;; If different key is pressed, it returns with; carry clear.;; Modification History;; 31 Dec 86    SEG;;    Simple code reduction.  No changes	in features.;DoKey		; 	lda EvtMessage	; look at char typed.	cmp #13	; RETURN = ok button	beq OK	cmp #27	; ESC = cancel button	beq Cancel	clc	; bad key so signal	that we must	rts	; continueOK	lda #1	; return result.	sta WhichButton	ldy #OKRectFinishUp		; 	ldx #HLRect	jsr MoveRect	jsr DarkButton	jsr LightButton	lda WhichButton	sec	rtsCancel	lda #2	sta WhichButton	ldy #CancelRect	bra FinishUp	eject;-------------------------------------------------;; DrawDialog;; This little routine draws the dialog.;; Modification History;; 31 Dec 86    SEG;;    Simple code reduction.  No changes	in features.;DrawDialog		; 	PushWord #PromptX	; first put up the user's prompt	PushWord #PromptY	_moveto	pei PromptPtr+2	pei PromptPtr	_DrawString	PushWord #VolX	; now the volume name	PushWord #VolY	_MoveTo	pei VolPtr+2	pei VolPtr	_DrawString	lda #1	ldy #OKRect	jsr DrawAButton	lda #2	ldy #CancelRectDrawAButton		; 	sta WhichButton	ldx #HLRect	jsr MoveRect	jmp LightButton	eject;-------------------------------------------------;; MoveRect;; Moves 8 bytes from <<0,x to <<0,y.;MoveRect		; 	lda |0,y	sta <0,x	lda |2,y	sta <2,x	lda |4,y	sta <4,x	lda |6,y	sta <6,x	rtsDestRect	DC.W 0,0,DialogHeight,DialogWidthCancelRect	DC.W DialogHeight-TopFace	DC.W LeftFace	DC.W DialogHeight-TopFace+ButHeight	DC.W LeftFace+ButWidthOKRect	DC.W DialogHeight-TopFace	DC.W DialogWidth-LeftFace-ButWidth	DC.W DialogHeight-TopFace+ButHeight	DC.W DialogWidth-LeftFace	ENDP*****************************************************************TLTextMountVolume	PROC EXPORT** This is the same call as TLMountVol except that it works in* text rather than in super hires graphics.** Assumptions:**     1) The machine is already in text	mode.*     2) The text screen may be trashed.** [3-Jun-91 DAL: Those assumptions are way out of date.  These*  days it's calling SaveTextState and RestoreTextState.]** This routine actually makes no OS calls.  It just returns* the button number	pressed by the user.  The application* then can make the	call that failed again and see if it* works.** By not guarenteeing the volume is mounted this routine is* more general (and	shorter).**** Inputs:*              PromptPtr : long*              VolPtr : long*              OKPtr : long*              CancelPtr : long** Outputs:*              ResultWord : word** External Refs:	import GoToXY** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************OrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3CancelPtr	equ RTL2+3OKPtr	equ CancelPtr+4VolPtr	equ OKPtr+4PromptPtr	equ VolPtr+4Result	equ PromptPtr+4TextStartX	equ 3PromptLine	equ 6VolLine	equ 9ButtonLine	equ 13;-------------------------------------------------;; The event record is kept on real zero	page; since this is saved and restored by this call.;	DSect 0EvtWhat	wordEvtMessage	longEvtWhen	longEvtWhere	longEvtModifiers	wordTheEvent	equ EvtWhat	phd	tsc	tcd	phb	phk	plb	pha	; Save the current text screen	pha	; environment	_SaveTextState	lda >CSWL	; save the input and output hooks	pha	lda >KSWL	pha	jsl IncBusyFlg	PushWord #0	PushLong #3	_SetOutputDevice	PushWord #0	PushLong #3	_SetInputDevice	PushWord #$FF	PushWord #0	_SetOutGlobals	PushWord #1	_InitTextDev	PushLong #Codes	jsl ToWriteCString	jsr DoBar	PushWord #$20	_WriteChar	lda #9BarLoop	pha	sep #$30	longa off	longi off	lda #39	sta >$24	rep #$30	longa on	longi on	PushLong #Edges	jsl ToWriteCString	pla	dec a	bpl BarLoop	sep #$30	longa off	longi off	lda #0	sta >$24	sta >$57B	rep #$30	longa on	longi on	jsr DoBar	PushWord #$FF	PushWord #$80	_SetOutGlobals	ldy #PromptLine	ldx #TextStartX	jsr GoToXY	PushLong PromptPtr	jsl ToWriteString	ldy #VolLine	ldx #TextStartX	jsr Gotoxy	PushLong VolPtr	jsl ToWriteString	ldy #ButtonLine	ldx #TextStartX	jsr Gotoxy	PushLong CancelPtr	jsl ToWriteString	lda [OKPtr]	and #$00FF	pha	lda #40-TextStartX+1	sbc 1,s	tax	pla	ldy #ButtonLine	jsr Gotoxy	PushLong OKPtr	jsl ToWriteStringNotESC		; ;-----------------------------------------------------;; First try to read	through the event manager;	lda #mDownMask+mUpMask+keyDownMask+autoKeyMask+deskAccMask	jsr GetThisEvent	; call event manager	bcs ReadMyself	; if error then try to read status of keys yourself 	beq NotESC	; null event returned	lda >EvtWhat	cmp #keyDownEvt	; Is it a key down event?	beq ItsKeyDown	cmp #autoKeyEvt	beq ItsKeyDown	cmp #deskAccEvt	; Is it a desk accessory event?	bne NotESC	; Neither keydown or deskacc so it must be a mouse down or;		; mouse up which we'll just disregard.	;; --- Call SystemEvent to handle calling the cda's ----------------------------------------;		pha	; space for result	ldx #EvtModifiers	; push all the values from the event record we got backloop	lda >0,x	; from GetOSEvent	pha	dex	dex	bpl loop	_SystemEvent	; handle <ctrl><open-apple><esc>	pla	; we don't care what we got back	bra NotESC	ItsKeyDown	lda >EvtMessage	; Get ASCII character that was typed.	bra GotKeyReadMyself	sep #$30	lda $E0C000	bpl NoKey	sta $E0C010NoKey	rep #$30	bpl NotESC	and #$7FGotKey	cmp #13	; we only care about RETURN and ESC	bne NotReturn	lda #1	bra DoneNotReturn	cmp #27	bne NotEsc	lda #2Done	sta Result	PushWord #1	; clear screen again.	_InitTextDev	pla	sta >KSWL	; input hook low	pla	sta >CSWL	; output hook low	_RestoreTextState	plb	ldy #16	ldx #0	pld	jml ToBusyStripNormalText		; 	sep #$30	longa off	longi off	lda #$FFCommonText	sta >$32	rep #$30	longa on	longi on	rtsInverseText		; 	sep #$30	longa off	longi off	lda #$7F	bra CommonText	longa on	longi onDoBar		; 	jsr InverseText	PushLong #Bar	jsl ToWriteCString	jsr NormalText	rtsToWriteCString		; 	ldx #$200C	jsl $E10004	rtlToWriteString		; 	ldx #$1A0C	jsl $E10004	rtl;-------------------------------------------------;; GetThisEvent;; Called to read character using event manager.;; Event mask is passed in a-reg.  boolean returned in a reg.;GetThisEvent		; 	pha	; space for result	pha	; use mask coming in	PushLong #TheEvent	_GetOSEvent	; call GetOSEvent instead of GetNextEvent because we don't;		; want keydowns to be passed onto the desk mgr	pla	rtsBar	DC.B '                                        ';	      1234567890123456789012345678901234567890	DC.B 0Edges	DC.B $20	DC.B $20	DC.B 0	DC.B $5A	DC.B $5F	DC.B 0Codes	DC.B 17,13,13,13,13,0	ENDPGoToXY	PROC	sep #$30	longa off	longi off	txa	; long address	sta >$24	tya	sta >$25	rep #$30	longa on	longi on	lda #0	pha	pha	pha	pha	pha	pha	pha	PushWord #$FC22	_fwentry	pla	pla	pla	pla	rts	ENDP	title ' TLMemRoutines'*****************************************************************TLMemRoutines2	PROC** Gets a handle of the size passed in the a-reg.  If GetMem* is used, attributes are passed from calling routine in* x-reg.  If TLNewhandle is used, attributes are TLAttributes.*** Inputs:*    a-reg  Size of	handle*    x-reg  attributes of handle (for GetMem only)** Outputs:*    a-reg  Low word of handle (or error)*    x-reg  high word of handle*    carry  set on error, clear on success** External Refs:*	none** Entry Points:	export TLGetMem2	entry TLNewHandle2*	longa on	; mode	longi on** Change History** 06 Oct 87    Steven Glass**    Added.** 17 Jun 88	Steven Glass** Combined this with TLNewHandle.  Code was almost identical* but duplicated.  By changing the calls to TLNewHandle to* use the a-reg and x-reg for output we could share code.*****************************************************************TLNewHandle2	ldx #TLAttributesTLGetMem2	pha	pha	pea $0000	pha	PushWord #TLUserID	phx	pha	pha	_NewHandle	bcs oops	pla	plx	rtsoops	plx	plx	rts	ENDP	END